};

// 2010.03.11 김봉석 대리 요청으로 접수시각을 거래소 제출시각으로, 처리시각을 거래소 접수시각으로 변경

scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    var urldep = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD_2.DataID = encodeURI(urldep);
    dts_DEP_CD_2.Reset();
    var urlemp = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO_2.DataID = encodeURI(urlemp);
    dts_EMP_NO_2.Reset();
    dts_FORM_CD.DataID = "/CodeAction.do?method=listListingFormCd&inputMessageId=LISTING_FROM_CD_OUT" + "&For=R&LD_MKT_TP_CD=" + scwin.gLdMktTp;
    dts_FORM_CD.Reset();
    dts_LIST_BZ_TP_CD.DataID = "/CodeAction.do?method=listListingBZTpCd&inputMessageId=LISTING_FROM_CD_OUT" + "&For=R&LD_MKT_TP_CD=" + scwin.gDepCd;
    dts_LIST_BZ_TP_CD.Reset();
    $c.stf.setObjectValue(cmb_DEP_CD_2, js_dep_cd);
    //setObjectValue(cmb_EMP_NO_1, js_emp_no) ;		

};
scwin.fn_GetParIsur_2 = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD_2);
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM_2);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur_2 = function(arrPar) {
    txb_ISUR_CD_2.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM_2.setValue(arrPar[0].COM_NM);
};



//2010.03.11 김봉석 대리 요청
// 접수상태 전체 선택시 모두 체크 되도록
scwin.fn_allCheck_2 = function() {
    var checkArray = [chb_stat_00, chb_stat_30, chb_stat_40];
    if (chb_stat_99.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(1);
        }
    }
    if (chb_stat_99.checked == false) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.fn_getCondValue = function(pCnt, pVal, vCode) {
    if (pCnt > 0) {
        pVal += "," + vCode + "";
    } else {
        pVal = vCode;
    }
    return pVal;
};
scwin.fn_getCondition_2 = function() {
    var vStatCnt = 0;
    var vStatCond = '';
    if (chb_stat_99.checked == true) {
        vStatCond = '';
        vStatCnt++;
    } else {
        if (chb_stat_00.checked == true) {
            vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '00');
            vStatCnt++;
        }
        if (chb_stat_30.checked == true) {
            vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '30');
            vStatCnt++;
        }
        if (chb_stat_40.checked == true) {
            vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '40');
            vStatCnt++;
        }
    }
    return vStatCond;
};
scwin.fn_Search = function() {
    var cond = scwin.fn_getCondition_2();
    //alert ('[cond]'+cond);

    if (chb_main_yn.checked == false && chb_atch_yn.checked == false) {
        $c.win.alert("제출유형은 한개이상 선택하십시오.");
        chb_main_yn.focus();
        return;
    }
    var url = "/ListedReceive.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listReceipt&inputMessageId=RECV_LSTRCV_INOUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD_2);
    url += "&FORM_CD=" + $c.stf.getObjectValue(cmb_FORM_CD);
    url += "&ACPT_SDATE=" + $c.stf.getObjectValue(edt_AcptSDate);
    url += "&ACPT_EDATE=" + $c.stf.getObjectValue(edt_AcptEDate);
    url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD_2);
    url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO_2);
    url += "&DISCLS_PROCS_STAT_CD=" + scwin.fn_getCondition_2();
    //url += "&DISCLS_PROCS_STAT_CD=" + getObjectValue(cmb_LIST_PROCS_STAT_CD);
    url += "&UP_DEP_CD=" + js_belngdepcd;
    url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp;
    url += "&MAIN_YN=" + $c.stf.getObjectValue(chb_main_yn);
    url += "&ATTCH_YN=" + $c.stf.getObjectValue(chb_atch_yn);
    //alert("vListMdCd :"+vListMdCd);
    dts_List_2.DataID = encodeURI(url);
    dts_List_2.Reset();
    $c.cm.ShowWin(grd_List_2);
};


// 클릭된 값 변수에 셋팅
scwin.fn_OpenDetail = function(row, colid) {
    scwin.fn_setContnId(row);
    if (colid == "FORM_KOR_NM") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, scwin.gViewerStat, scwin.vScrenID);
    } else if (colid == "ACPT_DDTM") {
        $c.stf.fn_OpenDisclAllList();
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.fn_setContnId = function(obj) {
    scwin.gViewerStat = "R"; // 처리시 뷰어=P,  조회시 뷰어=R
    if (eval(obj) > 0) {
        //그리드에서 선택시
        scwin.gAcptNo = dts_List_2.getCellData(eval(obj), "ACPT_NO");
        scwin.gMainFormCd = dts_List_2.getCellData(eval(obj), "FORM_CD");
        scwin.gFormVer = dts_List_2.getCellData(eval(obj), "FORM_VER");
        scwin.gIsurCd = dts_List_2.getCellData(eval(obj), "ISUR_CD");
    }
};
scwin.fn_ExcelDown = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_List_2, "접수처리목록", "", "2");
};
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
};
scwin.img_COM_NM_2_onclick = function() {
    //fn_GetPar = fn_GetParIsur_2;
    //fn_SetPar = fn_SetParIsur_2;
    //fn_PopFindCorpChrg(fr_SecuGrpId);
    $c.cm.IsurcdSearch(txb_ISUR_CD_2, txb_COM_NM_2); //상장폐지법인도나오게 변경 2009.06.04

};
scwin.dts_DEP_CD_2_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(cmb_DEP_CD_2, js_dep_cd);
};
scwin.dts_EMP_NO_2_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EMP_NO_2, js_emp_no) ;	

};
scwin.cmb_DEP_CD_2_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD_2);
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EMP_NO_2, '');
    }
    dts_EMP_NO_2.UseFilter = true;
    dts_EMP_NO_2.Filter();
    dts_EMP_NO_2.sort("DEP_CD", 0);
    //dts_EMP_NO_2.sort(); // W-Craft 주석처리 

};
scwin.dts_EMP_NO_2_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO_2.getCellData(row, "DEP_CD") == scwin.gDepCd || dts_EMP_NO_2.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.txb_ISUR_CD_2_onblur = function() {
    if (txb_ISUR_CD_2.getValue() == "") {
        txb_COM_NM_2.setValue("");
    }
};
scwin.chb_stat_99_onclick = function() {
    scwin.fn_allCheck_2();
};
scwin.chb_stat_00_onclick = function() {
    chb_stat_99.setValue(0);
};
scwin.chb_stat_30_onclick = function() {
    chb_stat_99.setValue(0);
};
scwin.chb_stat_40_onclick = function() {
    chb_stat_99.setValue(0);
};
scwin.dts_DEP_CD_2_OnLoadError = function() {
    $c.stf.alert_error(dts_DEP_CD_2);
};
scwin.dts_EMP_NO_2_OnLoadError = function() {
    $c.stf.alert_error(dts_EMP_NO_2);
};
scwin.dts_FORM_CD_OnLoadError = function() {
    $c.stf.alert_error(dts_FORM_CD);
};
scwin.dts_LIST_BZ_TP_CD_OnLoadError = function() {
    $c.stf.alert_error(dts_LIST_BZ_TP_CD);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt_2.setValue("총 " + dts_List_2.getTotalRow() + " 건");
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.grd_List_2_OnDblClick = function(row, colid) {
    scwin.fn_OpenDetail(row, colid);
};
scwin.btn_Search_2_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_2_onclick = function() {
    scwin.fn_ExcelDown();
};
scwin.img_AcptSDate_onclick = function() {
    popUpCalendar2(edt_AcptSDate);
};
scwin.img_AcptEDate_onclick = function() {
    popUpCalendar2(edt_AcptEDate);
};
scwin.btn_Close_2_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.cmb_PeriodTp_2_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp_2, "VALUE", cmb_PeriodTp_2.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_AcptSDate, edt_AcptEDate);
};
scwin.gform_onload = function() {
    if (js_market != "9") {
        //grd_List_1.ColumnProp("LD_MKT_TP_NM", "Show") = false;
        $c.cm.setColumnProp(grd_List_2, "LD_MKT_TP_NM", "Show", false);
        //grd_List_3.ColumnProp("LD_MKT_TP_NM", "Show") = false;

    }
    $c.cm.PanelToGroupBox(panel_Top_2);

    /* 2010.03.11 김봉석대리 요청(1927)
     *   default 2개월 
     */
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    var vCurMonth = $c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 2);
    edt_AcptSDate.setValue(vCurMonth);
    edt_AcptEDate.setValue(vCurDate);

    //edt_BzSDate.text = vCurMonth;
    //edt_BzEDate.text = vCurDate;

    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp_2);
    scwin.fn_SetCode();

    //CopyDataSet(dts_DEP_CD_3, dts_DEP_CD_2);
    //CopyDataSet(dts_EMP_NO_3, dts_EMP_NO_2);

    scwin.fn_Search();
};
